/**
 * Dilix — i18n (جهانی‌سازی سمتِ کلاینت)
 * رجیستریِ زبان‌ها + دیکشنریِ ترجمه + انتخابِ زبان از localStorage.
 * دیکشنری به‌تدریج کامل می‌شود؛ کلیدِ نایافته به fa و سپس خودِ کلید fallback می‌کند.
 */

export type Dir = "rtl" | "ltr";

export interface LocaleMeta {
  code: string;
  native: string;
  english: string;
  dir: Dir;
  defaultCurrency: string;
  flag: string;
}

export const LOCALES: Record<string, LocaleMeta> = {
  fa: { code: "fa", native: "فارسی", english: "Persian", dir: "rtl", defaultCurrency: "IRR", flag: "🇮🇷" },
  en: { code: "en", native: "English", english: "English", dir: "ltr", defaultCurrency: "USD", flag: "🇺🇸" },
  ar: { code: "ar", native: "العربية", english: "Arabic", dir: "rtl", defaultCurrency: "AED", flag: "🇸🇦" },
  tr: { code: "tr", native: "Türkçe", english: "Turkish", dir: "ltr", defaultCurrency: "TRY", flag: "🇹🇷" },
  ru: { code: "ru", native: "Русский", english: "Russian", dir: "ltr", defaultCurrency: "RUB", flag: "🇷🇺" },
  fr: { code: "fr", native: "Français", english: "French", dir: "ltr", defaultCurrency: "EUR", flag: "🇫🇷" },
  de: { code: "de", native: "Deutsch", english: "German", dir: "ltr", defaultCurrency: "EUR", flag: "🇩🇪" },
  es: { code: "es", native: "Español", english: "Spanish", dir: "ltr", defaultCurrency: "EUR", flag: "🇪🇸" },
  zh: { code: "zh", native: "中文", english: "Chinese", dir: "ltr", defaultCurrency: "CNY", flag: "🇨🇳" },
  hi: { code: "hi", native: "हिन्दी", english: "Hindi", dir: "ltr", defaultCurrency: "INR", flag: "🇮🇳" },
};

export const DEFAULT_LOCALE = "fa";
export const LS_LOCALE = "dilix_locale";
export const LS_CURRENCY = "dilix_currency";
export const LS_LANG_DISMISSED = "dilix_lang_suggest_dismissed";

export function localeMeta(code?: string | null): LocaleMeta {
  return (code && LOCALES[code]) || LOCALES[DEFAULT_LOCALE];
}

export function dirOf(code?: string | null): Dir {
  return localeMeta(code).dir;
}

