  "dash.earth.descDriver": { fa: "کاربران و مسیرهای دنیا را روی کره سه‌بعدی پیدا کن", en: "Find users and routes across the world on the 3D globe", ar: "اعثر على المستخدمين والمسارات حول العالم على الكرة ثلاثية الأبعاد", tr: "Dünyadaki kullanıcıları ve rotaları 3D küre üzerinde bul", ru: "Находите пользователей и маршруты по всему миру на 3D-глобусе", fr: "Trouvez des utilisateurs et des itinéraires du monde entier sur le globe 3D", de: "Finde Nutzer und Routen weltweit auf dem 3D-Globus", es: "Encuentra usuarios y rutas de todo el mundo en el globo 3D", zh: "在3D地球上找到世界各地的用户和路线", hi: "3D ग्लोब पर दुनिया भर के उपयोगकर्ता और मार्ग खोजें" },
  "dash.earth.descOther": { fa: "کاربران و تجار دنیا را روی کره سه‌بعدی پیدا کن", en: "Find users and traders across the world on the 3D globe", ar: "اعثر على المستخدمين والتجار حول العالم على الكرة ثلاثية الأبعاد", tr: "Dünyadaki kullanıcıları ve tüccarları 3D küre üzerinde bul", ru: "Находите пользователей и торговцев по всему миру на 3D-глобусе", fr: "Trouvez des utilisateurs et des commerçants du monde entier sur le globe 3D", de: "Finde Nutzer und Händler weltweit auf dem 3D-Globus", es: "Encuentra usuarios y comerciantes de todo el mundo en el globo 3D", zh: "在3D地球上找到世界各地的用户和商家", hi: "3D ग्लोब पर दुनिया भर के उपयोगकर्ता और व्यापारी खोजें" },
