/** ترجمهٔ یک کلید در زبانِ جاری (یا زبانِ داده‌شده). */
export function t(key: string, locale?: string | null): string {
  const loc = locale || getLocale();
  const row = DICT[key];
  if (!row) return key;
  return row[loc] ?? row[DEFAULT_LOCALE] ?? row["en"] ?? key;
}

export function getLocale(): string {
  if (typeof window === "undefined") return DEFAULT_LOCALE;
  return localStorage.getItem(LS_LOCALE) || DEFAULT_LOCALE;
}

export function getCurrency(): string {
  if (typeof window === "undefined") return localeMeta(DEFAULT_LOCALE).defaultCurrency;
  return localStorage.getItem(LS_CURRENCY) || localeMeta(getLocale()).defaultCurrency;
}

/** ذخیرهٔ محلیِ زبان/ارز + اعمالِ dir/lang روی <html>. */
export function applyLocale(locale: string, currency?: string): void {
  if (typeof window === "undefined") return;
  const meta = localeMeta(locale);
  localStorage.setItem(LS_LOCALE, meta.code);
  if (currency) localStorage.setItem(LS_CURRENCY, currency);
  const html = document.documentElement;
  html.setAttribute("lang", meta.code);
  html.setAttribute("dir", meta.dir);
}
